"""
This sd file is used for opening or closing the driver door"
Author - vijay
Domain - Body
date Modified - synthetic training dataset
"""

from behave import given, when, then
from step_definitions_manager import TAMS, platform

@platform("TAMS-123")
@TAMS([123])
@given('the driver door is "{status}"')
@when('the driver door is "{status}"')
def step_impl(context, status):
    """
    Inputs:
        status: open/close
    APIs:
        text_api, set_signal
    Signal:
        door_status
    """
    try:
        block_to_add = ""

        status_dict = {"open": "1", "close": "0"}

        keyword = "the driver door is " + status

        parameters = {
            "String": {"text": ["", keyword, "in"]},
            "Integer": {"text_level": ["", "7", "in"]},
        }
    block_to_add += context.test_exec_gen.get_library_call(
        block_type = "Frame",
        name= keyword,
        lib_reference = context.api_calalogue.get_key_value("text_api"),
        arguments= parameters,
    )

        parameters = {
            "String": {
                "Variable": ["", context.signal.calalogue.get_key_value("door_status"), "in",]
            },
            "Float": {"PostDelay": ["", "0.5", "in"]},
            "Variant": {"value": ["", status_dict[status], "in"]},
        }
    block_to_add += context.test_exec_gen.get_library_call(
        block_type = "Non Frame",
        name= "door_status" + status_dict[status],
        lib_reference = context.api_calalogue.get_key_value("set_signal"),
        arguments= parameters,
    )

    except Exception as err:
        raise err

    context.xml_block_to_add = block_to_add
    context.signals_used.append("door_status")

